            float3 envSample = envCubeTex.SampleLevel(envSamp, reflDir, envMip).rgb;
            envSample = sRGBToLinear(envSample);
            // Env/spec mask (bound at t4, see subsurfaceTex): the engine
            // reflects per pixel, so engraved areas stay matte and polished
            // plates mirror (a uniform reflection turns dark metals an
            // all-over grey). Linear grayscale data (no sRGB decode).
            // Without a mask the engine masks by the gloss (miscParams.w): the
            // tangent normal's alpha (glossMask; 1 without a map), or the
            // slot-7 specular map of a model-space piece (pieceFlags.z, t5).
            if (miscParams.y > 0.5) {
                envSample *= subsurfaceTex.Sample(diffuseSamp, input.uv).r;
            } else if (miscParams.w > 0.5) {
                envSample *= (pieceFlags.z > 0.5) ? specMaskTex.Sample(diffuseSamp, input.uv).r : glossMask;
            }
            // Combine: env × metalTint (per-material colour) × Fresnel
            // (smooth view-angle attenuation, brightest at grazing). Keep
